import{_ as o,o as a,c as l,a0 as t}from"./chunks/framework.DqMqoJl9.js";const h=JSON.parse('{"title":"Vue3 迁移","description":"","frontmatter":{},"headers":[],"relativePath":"vue/vue3-migration.md","filePath":"vue/vue3-migration.md","lastUpdated":1791573371000}'),s={name:"vue/vue3-migration.md"};function n(i,e,c,d,p,r){return a(),l("div",null,[...e[0]||(e[0]=[t(`<h1 id="vue3-迁移" tabindex="-1">Vue3 迁移 <a class="header-anchor" href="#vue3-迁移" aria-label="Permalink to &quot;Vue3 迁移&quot;">​</a></h1><h2 id="_1-vue3-迁移指南" tabindex="-1">1 Vue3 迁移指南 <a class="header-anchor" href="#_1-vue3-迁移指南" aria-label="Permalink to &quot;1 Vue3 迁移指南&quot;">​</a></h2><p><a href="https://v3-migration.vuejs.org/zh/" target="_blank" rel="noreferrer">Vue3 迁移指南 官方文档</a></p><h2 id="_2-vue3-新特性" tabindex="-1">2 Vue3 新特性 <a class="header-anchor" href="#_2-vue3-新特性" aria-label="Permalink to &quot;2 Vue3 新特性&quot;">​</a></h2><p><a href="https://v3-migration.vuejs.org/zh/" target="_blank" rel="noreferrer">详情见官方文档</a></p><ul><li><p>组合式 API</p></li><li><p>单文件组件中的组合式 API 语法糖 <code>&lt;script setup&gt;</code></p></li><li><p>Teleport 组件：可以将一个组件内部的一部分模板传送到外层的位置，例如全屏的模态框</p></li><li><p>Fragments 片段：组件支持多根节点</p></li><li><p>Emits 组件选项：声明由组件触发的自定义事件</p></li><li><p>来自 <code>@vue/runtime-core</code> 的 <code>createRenderer</code> API 用来创建自定义渲染函数</p></li><li><p>单文件组件中的状态驱动的 CSS 变量 (<code>&lt;style&gt;</code> 中的 <code>v-bind</code>)</p></li><li><p>SFC <code>&lt;style scoped&gt;</code> 新增全局规则和针对插槽内容的规则</p></li><li><p><code>Suspense</code> 实验性</p></li></ul><h2 id="_3-非兼容性改变" tabindex="-1">3 非兼容性改变 <a class="header-anchor" href="#_3-非兼容性改变" aria-label="Permalink to &quot;3 非兼容性改变&quot;">​</a></h2><p><a href="https://v3-migration.vuejs.org/zh/breaking-changes/" target="_blank" rel="noreferrer">非兼容性改变</a></p><h3 id="_3-1-全局-api" tabindex="-1">3.1 全局 API <a class="header-anchor" href="#_3-1-全局-api" aria-label="Permalink to &quot;3.1 全局 API&quot;">​</a></h3><p><strong>全局 Vue API 更改为使用应用程序实例</strong></p><p>Vue 2 没有 app 的概念，从同一个 Vue 构造函数创建的每个根实例共享相同的全局配置</p><table tabindex="0"><thead><tr><th>2.x 全局 API</th><th>3.x 实例 API (app)</th></tr></thead><tbody><tr><td>Vue.config</td><td>app.config</td></tr><tr><td>Vue.config.productionTip</td><td>移除</td></tr><tr><td>Vue.config.ignoredElements</td><td>app.config.compilerOptions.isCustomElement</td></tr><tr><td>Vue.component</td><td>app.component</td></tr><tr><td>Vue.directive</td><td>app.directive</td></tr><tr><td>Vue.mixin</td><td>app.mixin</td></tr><tr><td>Vue.use</td><td>app.use</td></tr><tr><td>Vue.prototype</td><td>app.config.globalProperties</td></tr><tr><td>Vue.extend</td><td>移除</td></tr></tbody></table><p><strong>全局和内部 API 都经过了重构，现已支持 TreeShaking</strong></p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// vue 2</span></span>
<span class="line"><span style="color:#D73A49;">import</span><span style="color:#24292E;"> Vue </span><span style="color:#D73A49;">from</span><span style="color:#032F62;"> &#39;vue&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">Vue.</span><span style="color:#6F42C1;">nextTick</span><span style="color:#24292E;">(() </span><span style="color:#D73A49;">=&gt;</span><span style="color:#24292E;"> {</span></span>
<span class="line"><span style="color:#6A737D;">  // 一些和 DOM 有关的东西</span></span>
<span class="line"><span style="color:#24292E;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// vue 3</span></span>
<span class="line"><span style="color:#D73A49;">import</span><span style="color:#24292E;"> { nextTick } </span><span style="color:#D73A49;">from</span><span style="color:#032F62;"> &#39;vue&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6F42C1;">nextTick</span><span style="color:#24292E;">(() </span><span style="color:#D73A49;">=&gt;</span><span style="color:#24292E;"> {</span></span>
<span class="line"><span style="color:#6A737D;">  // 一些和 DOM 有关的东西</span></span>
<span class="line"><span style="color:#24292E;">});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>受影响的 API</p><ul><li><code>Vue.nextTick</code></li><li><code>Vue.observable</code> (用 <code>Vue.reactive</code> 替换)</li><li><code>Vue.version</code></li><li><code>Vue.compile</code> (仅完整构建版本)</li><li><code>Vue.set</code> (仅兼容构建版本)</li><li><code>Vue.delete</code> (仅兼容构建版本)</li></ul><h3 id="_3-2-模板指令" tabindex="-1">3.2 模板指令 <a class="header-anchor" href="#_3-2-模板指令" aria-label="Permalink to &quot;3.2 模板指令&quot;">​</a></h3><ul><li><code>v-model</code> prop 和事件名称更改，<code>title.sync=&quot;pageTitle&quot;</code> 替换为 <code>v-model.title=&quot;pageTitle&quot;</code></li><li><code>template</code> 上使用 <code>v-for</code> 需要使用 key</li><li><code>v-if</code> 和 <code>v-for</code> 在同一个元素身上使用时的优先级发生了变化</li><li><code>v-bind=&quot;object&quot;</code> 现在是顺序敏感的</li><li><code>v-on:event.native</code> 移除。自定义事件需要用 emits 显式定义。未被定义为组件触发的所有事件监听器，会把它们作为原生事件监听器添加到子组件的根元素中 (除非在子组件的选项中设置了 <code>inheritAttrs: false</code>)</li></ul><h3 id="_3-3-组件" tabindex="-1">3.3 组件 <a class="header-anchor" href="#_3-3-组件" aria-label="Permalink to &quot;3.3 组件&quot;">​</a></h3><ul><li><p>异步组件现在需要通过 <code>defineAsyncComponent</code> 方法进行创建</p></li><li><p>组件事件现在应该使用 <code>emits</code> 选项进行声明</p></li><li><p>函数式组件只能通过纯函数进行创建</p></li><li><p>单文件组件 <code>&lt;template&gt;</code> 标签的 <code>functional attribute</code> 和函数式组件的 <code>functional</code> 选项已被移除</p></li></ul><h3 id="_3-4-渲染函数" tabindex="-1">3.4 渲染函数 <a class="header-anchor" href="#_3-4-渲染函数" aria-label="Permalink to &quot;3.4 渲染函数&quot;">​</a></h3><ul><li><p><code>$listeners</code> 被移除或整合到 <code>$attrs</code></p></li><li><p><code>$attrs</code> 现在包含 <code>class</code> 和 <code>style attribute</code></p></li><li><p>渲染函数 API 更改</p></li><li><p><code>$scopedSlots property</code> 已移除，所有插槽都通过 <code>$slots</code> 作为函数暴露</p></li></ul><h3 id="_3-5-被移除的-api" tabindex="-1">3.5 被移除的 API <a class="header-anchor" href="#_3-5-被移除的-api" aria-label="Permalink to &quot;3.5 被移除的 API&quot;">​</a></h3><ul><li><p><code>v-on</code> 不支持 <code>keyCode</code>，<code>KeyboardEvent.keyCode</code> 已被废弃</p></li><li><p><code>$on</code>、<code>$off</code> 和 <code>$once</code> 实例方法</p></li><li><p>过滤器 <code>filter</code>，使用计算属性或者方法替代</p></li><li><p>全局函数 <code>set</code> 和 <code>delete</code> 以及实例方法 <code>$set</code> 和 <code>$delete</code>。基于代理的变化检测已经不再需要它们了</p></li><li><p><code>$children</code>。<code>2.x</code> 中可以使用 <code>this.$children</code> 访问当前实例的直接子组件。建议使用模板引用 <code>ref</code></p></li><li><p><code>$destroy</code> 实例方法。用户不应该再手动管理单个 Vue 组件的生命周期</p></li><li><p>内联模板 <code>attribute</code></p></li><li><p><code>propsData</code> 选项</p></li></ul><h3 id="_3-6-自定义元素" tabindex="-1">3.6 自定义元素 <a class="header-anchor" href="#_3-6-自定义元素" aria-label="Permalink to &quot;3.6 自定义元素&quot;">​</a></h3><ul><li>自定义元素检测现在在模板编译时执行</li><li>特殊的 <code>is</code> attribute 的使用被严格限制在被保留的 <code>&lt;component&gt;</code> 标签中</li></ul><h3 id="_3-7-其他小改变" tabindex="-1">3.7 其他小改变 <a class="header-anchor" href="#_3-7-其他小改变" aria-label="Permalink to &quot;3.7 其他小改变&quot;">​</a></h3><ul><li><p><code>destroyed</code> 生命周期选项被重命名为 <code>unmounted</code></p></li><li><p><code>beforeDestroy</code> 生命周期选项被重命名为 <code>beforeUnmount</code></p></li><li><p>来自 <code>mixin</code> 的 <code>data</code> 选项现在为浅合并</p></li><li><p><code>Props</code> 的 <code>default</code> 工厂函数不再可以访问 <code>this</code> 上下文</p></li><li><p>自定义指令的 API 已更改为与组件生命周期一致，且 <code>binding.expression</code> 已移除</p></li><li><p>当侦听一个数组时，只有当数组被替换时，回调才会触发，如果需要在变更时触发，则必须指定 <code>deep</code> 选项</p></li><li><p>没有特殊指令的标记 (<code>v-if/else-if/else</code>、<code>v-for</code> 或 <code>v-slot</code>) 的 <code>&lt;template&gt;</code> 现在被视为普通元素，并将渲染为原生的 <code>&lt;template&gt;</code> 元素，而不是渲染其内部内容</p></li><li><p><code>data</code> 选项应始终被声明为一个函数</p></li><li><p><code>Attribute</code> 强制策略已更改</p></li><li><p><code>Transition</code> 的一些 <code>class</code> 被重命名</p></li><li><p><code>&lt;TransitionGroup&gt;</code> 不再默认渲染包裹元素</p></li><li><p>已挂载的应用不会替换它所挂载的元素</p></li><li><p>生命周期的 <code>hook:</code> 事件前缀改为 <code>vue:</code></p></li></ul>`,28)])])}const b=o(s,[["render",n]]);export{h as __pageData,b as default};
